const VALID_OPERATIONS = new Set(['add', 'subtract', 'multiply', 'divide']);

const OPERATIONS = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b,
};

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers',
      inputSchema: {
        type: 'object',
        properties: {
          a: { type: 'number', description: 'First numeric operand' },
          b: { type: 'number', description: 'Second numeric operand' },
          operation: {
            type: 'string',
            enum: ['add', 'subtract', 'multiply', 'divide'],
            description: 'Arithmetic operation to perform',
          },
        },
        required: ['a', 'b', 'operation'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const { a, b, operation } = args;

  if (a === undefined || b === undefined || operation === undefined) {
    throw new Error('Missing required field: a, b, and operation are required');
  }

  if (typeof a !== 'number' || typeof b !== 'number' || !Number.isFinite(a) || !Number.isFinite(b)) {
    throw new Error('a and b must be finite numbers');
  }

  if (!VALID_OPERATIONS.has(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  if (operation === 'divide' && b === 0) {
    throw new Error('Division by zero');
  }

  const result = OPERATIONS[operation](a, b);
  return { content: [{ type: 'text', text: String(result) }] };
}

